    {
      "category": "other",
      "components": ["FCC2", "NAVC2"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47"],
      "nets": ["NET0129", "NET0050", "NET0006", "NET0039"],
      "observed": "Both STM32s' VCAP pins are routed onto external signal nets, with no VCAP capacitors shown. On FCC2, pins 48 and 73 connect to NET0129 and NET0050, which are also on the UART3_FCC2 connector. On NAVC2, pins 31 and 47 connect to NET0006 and NET0039; NET0006 is on the I2C3_NAVC connector, and NET0039 is used in the USB-debug circuitry.",
      "expected": "The STM32 VCAP pins should be used for the internal core-regulator decoupling required by the MCU datasheets, with the specified capacitors to ground, not routed as external interface signals.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "VCAP 48 NET0129; VCAP 73 NET0050 (FCC sheet, page 2/6)"
        },
        {
          "source": "schematic",
          "quote": "UART3_FCC2: NET0129, NET0050 (FCC Peripherals sheet, page 5/6)"
        },
        {
          "source": "schematic",
          "quote": "VCAP_1 31 NET0006; VCAP_2 47 NET0039 (NAVC sheet, page 3/6)"
        },
        {
          "source": "schematic",
          "quote": "I2C3_NAVC: NET0006 (NAVC Peripherals sheet, page 6/6); NET0039 appears in USB debug circuitry (Connections sheet, page 4/6)"
        }
      ],
      "impact": "The missing VCAP decoupling and loading or use of these internal regulator pins as interface signals can prevent reliable MCU core-regulator operation, causing resets or failure to run; the associated connectors will not provide the intended signals.",
      "confidence": 0.99
    }
  ],
  "summary": "Both MCU VCAP pins are shown on external signal nets instead of being decoupled as required. This is a serious power-integrity and connectivity error that can prevent reliable operation of both processors."
}

